'use strict';

// Direct file previews can't fetch JSON. Export only the render index from the same importer manifest.
module.exports = function localManifest(m) {
  const keys = ['schema', 'characters', 'ground', 'facades', 'props', 'weapons', 'pickups', 'effects', 'vehicles'];
  const entries = keys.map(key => '  ' + key + ': ' + JSON.stringify(m[key]));
  return '// Generated by prepare-art.js for direct file previews.\nP.LocalArtManifest = {\n' + entries.join(',\n') + '\n};\n';
};
